BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(31);
SELECT ok(to_regprocedure('app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)') IS NOT NULL,'private dual authority source exists');
SELECT ok((SELECT pg_get_userbyid(proowner)='schoolos_authz_reader' FROM pg_proc WHERE oid='app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)'::regprocedure),'narrow NOLOGIN authorization owner');
SELECT ok((SELECT prosecdef FROM pg_proc WHERE oid='app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)'::regprocedure),'authorization source uses owned definer');
SELECT ok((SELECT EXISTS(SELECT 1 FROM unnest(proconfig) v WHERE regexp_replace(v,'[[:space:]]','','g')='search_path=pg_catalog,pg_temp') FROM pg_proc WHERE oid='app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)'::regprocedure),'fixed restricted search_path');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'authenticated cannot call authority source');
SELECT ok(NOT has_function_privilege('anon','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'anon cannot call authority source');
SELECT ok(NOT has_function_privilege('service_role','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'service role cannot call authority source');
SELECT ok(NOT has_function_privilege('schoolos_student_executor','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'D1 student executor cannot bypass orchestrator');
SELECT ok(NOT has_function_privilege('schoolos_platform_executor','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'file platform executor cannot call authority source');
SELECT ok(NOT has_function_privilege('schoolos_evidence_writer','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'audit writer cannot call authority source');
SELECT ok(has_function_privilege('schoolos_workflow_executor','app_private.db03_student_create_dual_authority(uuid,uuid,uuid,uuid)','EXECUTE'),'Principal workflow may compose authority proof');
SELECT ok(has_column_privilege('schoolos_authz_reader','app_private.class_offerings','campus_id','SELECT'),'authorization reader can inspect Class campus');
SELECT ok(has_column_privilege('schoolos_authz_reader','app_private.section_offerings','class_offering_id','SELECT'),'authorization reader can inspect Section class ancestry');
SELECT ok((SELECT count(*)=1 FROM pg_policies WHERE schemaname='app_private' AND tablename='class_offerings' AND policyname='db03_student_create_authz_class_read' AND cmd='SELECT'),'D1 Class authorization read policy');
SELECT ok((SELECT count(*)=1 FROM pg_policies WHERE schemaname='app_private' AND tablename='section_offerings' AND policyname='db03_student_create_authz_section_read' AND cmd='SELECT'),'D1 Section authorization read policy');
SELECT ok((SELECT count(*)=1 FROM pg_policies WHERE schemaname='app_private' AND tablename='operation_contracts' AND policyname='db03_student_create_operation_read' AND cmd='SELECT'),'student.create operation authorization read policy');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.class_offerings'::regclass),'D1 Class row-level security intact');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.section_offerings'::regclass),'D1 Section row-level security intact');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT'),'client cannot forge Student handoff');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.students','INSERT'),'Principal executor cannot directly insert Student');
SELECT ok(NOT has_table_privilege('authenticated','app_private.students','INSERT'),'client cannot directly insert Student');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_handoff_mutation_disabled' AND tgenabled='O'),'D1 trusted handoff still write-disabled');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND tgenabled='O'),'policy binding still write-disabled');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_number_allocations_mutation_disabled' AND tgenabled='O'),'admission number writer still disabled');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_principal_approval_mutation_disabled' AND tgenabled='O'),'final approval writer still disabled');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_principal_approvals),'no final approval created');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_student_handoffs),'no Student handoff created');
SELECT ok((SELECT count(*)=0 FROM app_private.students),'no Student created in disposable fixture');
SELECT ok((SELECT count(*)=0 FROM app_private.operation_contracts WHERE code='student.create' AND enabled),'frozen D1 student.create contract not enabled');
SELECT is(app_private.db03_student_create_dual_authority(NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid),NULL::bytea,'no actor or destination fails closed');
SELECT is(app_private.db03_student_create_dual_authority('00000000-0000-0000-0000-000000000001'::uuid,'00000000-0000-0000-0000-000000000002'::uuid,'00000000-0000-0000-0000-000000000003'::uuid,'00000000-0000-0000-0000-000000000004'::uuid),NULL::bytea,'forged Principal cannot produce D1 dual authority');
SELECT * FROM finish();
ROLLBACK;
